using System;
using System.Drawing;
using System.Windows.Forms;

namespace SnuWatcher.Desktop;

/// <summary>
/// The application icon (Assets/SnuWatcher.ico, generated by scripts/New-AppIcon.ps1) is compiled into the exe;
/// its shortcut, taskbar button and WPF windows use that copy. The tray reads the same icon back from the exe.
/// </summary>
internal static class AppIcon
{
    /// <summary>The exe's icon at the current small-icon size. The caller owns and disposes it.</summary>
    internal static Icon CreateForTray()
    {
        var path = Environment.ProcessPath;
        var icon = path is null ? null : Icon.ExtractIcon(path, 0, SystemInformation.SmallIconSize.Width);
        // A missing icon must never stop the window from opening.
        return icon ?? (Icon)SystemIcons.Application.Clone();
    }
}
